 const sessionsNow=engagementNow.reduce((sum,r)=>sum+r.sessions,0),sessionsBefore=engagementBefore.reduce((sum,r)=>sum+r.sessions,0);const completedNow=engagementNow.reduce((sum,r)=>sum+r.completed,0),completedBefore=engagementBefore.reduce((sum,r)=>sum+r.completed,0);
