 const deltaBadge=(delta:number|null)=><span className={'delta '+(delta===null?'neutral':delta>=0?'positive':'negative')}>{delta===null?'—':<>{delta>=0?<ArrowUpRight size={13}/>:<ArrowDownRight size={13}/>} {Math.abs(delta).toFixed(1)}%</>}</span>;
