 if(data&&topSessionChannel&&topSessionChannel.share>=50)actions.push(`${sessionChannelName(topSessionChannel.name)}贡献 ${topSessionChannel.share.toFixed(1)}% Sessions，避免单一来源依赖；为第二大来源安排一个可追踪的商品/促销入口并比较其 Session 与订单表现。`);
 if(!actions.length&&data){const nextChannel=sessionChannels.find(s=>s.name!==topSessionChannel?.name);actions.push(`当前未触发明显下滑预警；维持主力来源 ${topSessionChannel?sessionChannelName(topSessionChannel.name):'的流量入口'}，选取${nextChannel?sessionChannelName(nextChannel.name):'第二来源'}做小规模素材或落地页测试，并用 CR、订单和 AOV 评估是否放量。`);if(topSkuByRevenue)actions.push(`保持「${topSkuByRevenue.title}」库存与核心坑位，增加一个关联 SKU/套装测试，按净售件数和净销售额复盘。`)}
