 const maxY=Math.max(1,...series.flatMap(r=>[r.value,r.previous]))*1.18;const chartW=860,chartH=240,padL=65,padR=18,padT=24,padB=34;const ix=(i:number)=>padL+i*(chartW-padL-padR)/Math.max(1,series.length-1);const iy=(v:number)=>padT+(1-v/maxY)*(chartH-padT-padB);
