 const sources=[...new Set(selected.map(r=>r.sales_channel))].map(name=>({name,rows:selected.filter(r=>r.sales_channel===name)})).filter(s=>s.name.toLowerCase().includes(search.toLowerCase()));
 function csv(){if(!data)return;const body=[['日期','店铺','平台','原始渠道','销售总额 ('+data.shop.currencyCode+')','净销售额','订单数','折扣','销售冲回'],...selected.map(r=>[r.day,r.shop_name,nameOf(r.platform),r.sales_channel,r.total_sales,r.net_sales,r.orders,r.discounts,r.sales_reversals])].map(line=>line.map(v=>{let s=String(v);if(typeof v==='string'&&/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\ufeff'+body],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`channel-desk-${data.mode}-${storeScope}-${platform}-${data.range.start}-${data.range.end}.csv`;a.click();URL.revokeObjectURL(url);setToast('已导出当前平台与日期范围的数据')}
